import{_ as s,l as c,o as a,c as l,v as o,p as d,x as t,d as i,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"系统调用路径","description":"","frontmatter":{"title":"系统调用路径","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/syscall-path.md","filePath":"cs/syscall-path.md","lastUpdated":1789023840000}'),E={name:"cs/syscall-path.md"};function h(m,e,B,_,A,u){const r=c("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="系统调用路径" tabindex="-1">系统调用路径 <a class="header-anchor" href="#系统调用路径" aria-label="Permalink to &quot;系统调用路径&quot;">​</a></h1><div class="epigraph"><p>系统调用把用户程序连到操作系统；它看起来像普通过程调用，实际经过陷入与参数校验。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems 整理</footer></div><p><a href="/cs/trapframe">上一课</a>让内核能在线程之间换上下文。<a href="/cs/privilege-rings">特权级</a>禁止用户直接碰设备。<a href="/cs/kernel-user">内核与用户态</a>只命名了门。缺口是：用户要读文件、要 <code>wait</code>，必须走一条<strong>自愿陷入</strong>的固定路径，而不能跳进内核任意地址。本课只钉这条路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把内核函数地址当普通 <code>call</code> 目标，用户可以带着任意栈进去，校验全无。硬件因此提供陷入指令：切特权、跳到唯一入口（或一小张入口表），把系统调用号放在约定寄存器里。缺口不是新的上下文格式，而是从用户 ABI 到内核实现函数的那一段：编号、拷贝参数、执行、写回返回值、再按<a href="/cs/exception-interrupt-entry">异常入口</a>返回。</p><p>本课不把每个 Unix 调用列成表，也不讲 <code>ioctl</code> 的全部设备语义。</p><p><span class="marginnote">libc 把 <code>read</code> 写成用户函数；真正的陷入在最里一层。POSIX 是接口，陷入指令是实现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户：把调用号与参数放入约定位置，执行陷入。内核入口：保存状态（可与切换共用帧），按号跳到实现，从用户地址空间<strong>拷贝</strong>入参（不能信任用户指针一直有效），执行，把返回值或 <code>errno</code> 写回，再 <code>sret</code>/<code>iret</code>。若调用要阻塞，入口路径会走进上一课的切换，醒来后从同一路径返回。</p>',9)),(a(),d(p,null,{default:t(()=>[n(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIB%5B%22%E7%94%A8%E6%88%B7%E5%BA%93%E5%8C%85%E8%A3%85%22%5D%20--%3E%20TRAP%5B%22%E9%99%B7%E5%85%A5%E6%8C%87%E4%BB%A4%22%5D%0A%20%20TRAP%20--%3E%20DISP%5B%22%E6%8C%89%E8%B0%83%E7%94%A8%E5%8F%B7%E5%88%86%E5%8F%91%22%5D%0A%20%20DISP%20--%3E%20COPY%5B%22%E6%A0%A1%E9%AA%8C%E5%B9%B6%E6%8B%B7%E8%B4%9D%E5%8F%82%E6%95%B0%22%5D%0A%20%20COPY%20--%3E%20IMPL%5B%22%E5%86%85%E6%A0%B8%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20IMPL%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E7%94%A8%E6%88%B7%E6%80%81%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>路径把「请求服务」从「执行内核代码」里隔开：用户永远不持有内核指令指针。参数拷贝是因为<a href="/cs/paging-vm">分页</a>下用户指针可能缺页或指向内核；内核必须用自己的映射安全地读。返回时特权降回用户，PC 指向陷入指令的下一条。</p><p>同一条路径既服务文件，也服务后课的 <code>clone</code>、<code>mmap</code>、套接字。本课只要求：凡跨特权的请求，都长这样。设备完成则往往先走中断，再唤醒阻塞在系统调用上的线程——那是下一课下半部。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不对比 <code>int 0x80</code>、<code>syscall</code>、<code>svc</code> 的编码，不把 seccomp 与能力模型写成安全课。也不讨论 VDSO 把部分读时钟留在用户态：那是加速，不改变「改内核状态必须陷入」。</p><p>调用号空间是 ABI 的一部分，与 libc 版本绑定；本课不把兼容层写成另一操作系统。</p><p>后课默认：用户要内核做事，就走系统调用路径；阻塞调用会切换。设备如何在路径之外把 CPU 抢回去，下一课讲中断下半部。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>系统调用是自愿陷入：编号、校验拷贝、执行、返回。</li><li>用户指针不可信；内核用自己的映射读入参。</li><li>阻塞会触发上下文切换；异步设备完成靠下一课。</li><li>出处：Tanenbaum and Bos, <em>MOS</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const T=s(E,[["render",h]]);export{P as __pageData,T as default};
